}

/* stylelint-disable selector-pseudo-element-no-unknown */
::ng-deep .custom-arrow-tooltip {
  background-color: var(--color-tooltip);
  color: var(--white);
  padding: 0 4px;
  border-radius: 6px;
  font-size: 12px;
  position: relative;
  text-align: center;
  max-width: 260px;
  box-shadow: 0 2px 10px rgb(0 0 0 / 30%);
}

::ng-deep .input-component .cdk-overlay-pane .custom-arrow-tooltip::after {
  content: "";
  position: absolute;
  top: -6px;
  rotate: 180deg;
  right: 50%;
  transform: translateX(-50%);
  width: 0;
  height: 0;
  border-left: 8px solid transparent;
  border-right: 8px solid transparent;
  border-top: 8px solid var(--color-tooltip);
}
/* stylelint-enable selector-pseudo-element-no-unknown */

