}

.cao-tab-header--align-center .cao-tab-label-list { justify-content: center; }
.cao-tab-header--align-end    .cao-tab-label-list { justify-content: flex-end; }
.cao-tab-header--align-start  .cao-tab-label-list { justify-content: flex-start; }

.cao-tab-label {
  width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  align-items: center;
  gap: var(--cao-tab-label-gap);
  height: var(--cao-tab-label-height);
  padding: 0 var(--cao-tab-label-px);

