  font-size:   var(--cao-tab-font-size);
  font-weight: var(--cao-tab-font-weight);
  color: var(--cao-tab-color-text);
  white-space: nowrap;

  background: transparent;
  border: none;
  border-radius: var(--cao-tab-radius) var(--cao-tab-radius) 0 0;
  cursor: pointer;
  user-select: none;
  transition: color 180ms ease, background-color 180ms ease;

  outline: none;
