  bottom: 0;
  left: 0;
  height: 100%;
  background-color: var(--cao-tab-color-ink-bar);
  border-radius: 2px 2px 0 0;
  transition-property: transform, width;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  transition-duration: 300ms; /* sobrescrito por JS */
}

.cao-tab-body-wrapper {
  position: relative;
